<script setup lang="ts">
import { nextTick, onMounted, ref } from "vue";
withDefaults(defineProps<{title:string;confirmText?:string;danger?:boolean;busy?:boolean;confirmDisabled?:boolean}>(), {confirmText:"确认"});
const emit=defineEmits<{confirm:[];cancel:[]}>();const panel=ref<HTMLElement|null>(null);
onMounted(async()=>{await nextTick();(panel.value?.querySelector("input,textarea,select,button") as HTMLElement|null)?.focus()});
function key(e:KeyboardEvent){if(e.key==="Escape"){e.preventDefault();emit("cancel")}else if(e.key==="Enter"&&!e.shiftKey&&(e.target as HTMLElement).tagName!=="TEXTAREA"){e.preventDefault();emit("confirm")}}
</script>
<template><Teleport to="body"><div class="veil" @keydown="key"><section ref="panel" class="dialog" role="dialog" aria-modal="true"><header><h2>{{title}}</h2></header><main><slot/></main><footer><button @click="$emit('cancel')">取消</button><button :class="{primary:!danger,danger}" :disabled="busy||confirmDisabled" @click="$emit('confirm')">{{confirmText}}</button></footer></section></div></Teleport></template>
<style scoped>.veil{position:fixed;inset:0;z-index:1000;background:rgba(25,20,28,.48);display:grid;place-items:center;padding:18px}.dialog{width:min(520px,100%);max-height:calc(100vh - 36px);display:flex;flex-direction:column;background:var(--bg-panel);border:1px solid var(--border);border-radius:12px;box-shadow:var(--shadow);color:var(--text)}header{padding:16px 18px;border-bottom:1px solid var(--border)}h2{margin:0;font-size:var(--font-size-title)}main{padding:18px;overflow:auto;min-height:0}footer{padding:12px 18px;display:flex;justify-content:flex-end;gap:8px;border-top:1px solid var(--border)}button{min-height:var(--control-height);padding:6px 14px;border:1px solid var(--border);border-radius:7px;background:var(--surface);color:var(--text);cursor:pointer}.primary{background:var(--accent);color:#fff;border-color:var(--accent)}.danger{color:var(--danger)}</style>
